import json,csv,re,statistics as st
T={}
for l in open('data/judge_transcripts.jsonl'):
    d=json.loads(l);m=re.findall(r'FINAL SCORE:\s*(\d+)',d['judge_output']);T[d['rating_id']]=(d,[int(x) for x in m])
rows=list(csv.DictReader(open('data/scores.csv')))
