for r in rows:
    d,m=T[r['rating_id']]
    if len(m)!=1 or m[0]!=int(r['score']) or d['displayed_label']!=r['displayed_label'] or d['session']!=int(r['session']) or d['response_id']!=r['response_id']: mis.append((r,m,d['displayed_label'],d['session']))
print(len(mis))
for x in mis:print(x)
def eff(get):
    by={}
